properties.query:
// Detects the user of certutil to decode commands
// Attackers use this for obfuscation
let cmd_any = dynamic(["-decode","-encode","-verifyctl","-decodehex"]);
let query1 =
_Im_ProcessCreate(commandline_has_any=cmd_any,targetprocess_has_any="certutil.exe");
// Detects suspicious usage of legitimate certutil.exe to download malware payloads
let cmd_all2 = dynamic(["urlcache","split"]);
let query2 =
_Im_ProcessCreate(commandline_has_all=cmd_all2,targetprocess_has_any="certutil.exe");
union isfuzzy=true
query1,query2
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessId) or isnotempty(CommandLine)
